import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class FastDateFormat_format_TriageGen2Test {

    @Test
    public void testFormatWithDefaultInstance() {
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy-MM-dd");
        Date date = new Date(1234567890000L); // 2009-02-13
        String result = fdf.format(date);
        assertEquals("2009-02-13", result);
    }

    @Test
    public void testFormatWithSpecificTimeZone() {
        TimeZone tz = TimeZone.getTimeZone("GMT+8");
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy-MM-dd HH:mm:ss", tz);

        // 2023-01-01 00:00:00 GMT+8 is 2022-12-31 16:00:00 UTC
        long millis = TimeZone.getTimeZone("UTC").parse("2022-12-31 16:00:00").getTime();
        // Since we can't easily parse in test without more tools, let's use a fixed millis
        // 1672531200000L is 2023-01-01 00:00:00 GMT+8
        Date date = new Date(1672531200000L);

        String result = fdf.format(date);
        assertEquals("2023-01-01 00:00:00", result);
    }

    @Test
    public void testFormatWithLocale() {
        // Test with French locale to ensure locale-specific formatting (e.g., month names)
        FastDateFormat fdf = FastDateFormat.getInstance("MMMM", Locale.FRENCH);
        Calendar cal = Calendar.getInstance(Locale.FRENCH);
        cal.set(2023, Calendar.JANUARY, 1);
        Date date = cal.getTime();

        String result = fdf.format(date);
        // January in French is "janvier"
        assertEquals("janvier", result.toLowerCase());
    }

    @Test
    public void testFormatWithDateStyle() {
        FastDateFormat fdf = FastDateFormat.getDateInstance(Calendar.LONG, Calendar.SHORT);
        Date date = new Date(1672531200000L); // 2023-01-01
        String result = fdf.format(date);
        assertNotNull(result);
        // Result varies by system locale, but should not be null or empty
        assert(result.length() > 0);
    }

    @Test
    public void testFormatWithDateTimeStyle() {
        FastDateFormat fdf = FastDateFormat.getDateTimeInstance(Calendar.MEDIUM, Calendar.MEDIUM);
        Date date = new Date(1672531200000L);
        String result = fdf.format(date);
        assertNotNull(result);
        assert(result.length() > 0);
    }

    @Test
    public void testFormatWithComplexPattern() {
        FastDateFormat fdf = FastDateFormat.getInstance("E, dd MMM yyyy HH:mm:ss Z");
        Date date = new Date(1672531200000L);
        String result = fdf.format(date);
        // Example: Sun, 01 Jan 2023 00:00:00 +0800
        // We check if it contains key segments to avoid brittle tests across environments
        assert(result.contains("2023"));
        assert(result.contains("Jan"));
    }

    @Test
    public void testFormatWithNullDate() {
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");
        try {
            fdf.format(null);
        } catch (NullPointerException e) {
            // Expected behavior for many formatters when passing null to format(Date)
        }
    }
}
